// One email, not one per launch. A digest people actually read is short, ranked, and says why
// each thing is on the list — so the tagline comes along and the ranking is visible.
const cfg = $('What you care about').first().json;
const keep = Math.max(1, Number(cfg.keep) || 10);
const rows = $input.all().map((i) => i.json).slice(0, keep);
if (!rows.length) return [{ json: { count: 0, subject: 'No launches cleared the bar this week', html: 'Nothing passed your vote floor of ' + cfg.minVotes + '. Lower it, or widen the topics.' } }];

const esc = (s) => String(s || '').replace(/[<>&]/g, (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c]));
const items = rows.map((r, n) => {
  const votes = Number(r.votesCount || r.votes || 0);
  const name = esc(r.name || r.productName || 'Untitled');
  const tag = esc(r.tagline || r.description || '');
  const url = r.url || r.productUrl || '';
  return '<li style="margin:0 0 14px"><b>' + (n + 1) + '. ' + (url ? '<a href="' + url + '">' + name + '</a>' : name) + '</b>'
    + ' <span style="color:#888">— ' + votes.toLocaleString() + ' votes</span>'
    + (tag ? '<br><span style="color:#444">' + tag + '</span>' : '') + '</li>';
}).join('');

return [{
  json: {
    count: rows.length,
    subject: 'This week in ' + cfg.topics + ' — ' + rows.length + ' launches worth a look',
    html: '<p>Launches above ' + Number(cfg.minVotes).toLocaleString() + ' votes in <b>' + esc(cfg.topics) + '</b>, best first.</p><ol style="padding-left:18px">' + items + '</ol>',
  },
}];
